from functools import cache

@cache
def fib(n):
    return n if n < 2 else fib(n - 1) + fib(n - 2)

print(fib(90))           # 2880067194370816120, instantly
print(fib.cache_info())  # CacheInfo(hits=88, misses=91, maxsize=None, currsize=91)

@cache
def total(nums):
    return sum(nums)
# total([1, 2]) -> TypeError: unhashable type: 'list'
print(total((1, 2)))     # 3

