from functools import cache

def count_splits(word, vocab):
    words = frozenset(vocab)          # hashable and O(1) lookups

    @cache
    def ways(start):                  # cache on the int; word and words come from the closure
        if start == len(word):
            return 1
        return sum(ways(end) for end in range(start + 1, len(word) + 1)
                   if word[start:end] in words)

    return ways(0)

print(count_splits('catsand', ['cat', 'cats', 'and', 'sand']))  # 2

